fn find_spec(table: &'static [Spec], code: u16) -> Option<&'static Spec> {
    table
        .binary_search_by_key(&code, |spec| spec.code)
        .ok()
        .map(|index| &table[index])
}

/// The operation with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn operation(code: OperationCode) -> Option<&'static Spec> {
    find_spec(OPERATIONS, code.0)
}

/// The device property with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn property(code: PropertyCode) -> Option<&'static Spec> {
    find_spec(PROPERTIES, code.0)
}

/// The event with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn event(code: EventCode) -> Option<&'static Spec> {
    find_spec(EVENTS, code.0)
}

/// The vendor response with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn response(code: u16) -> Option<&'static Spec> {
    find_spec(RESPONSES, code)
}

/// The object format with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn object_format(code: u16) -> Option<&'static Spec> {
    find_spec(OBJECT_FORMATS, code)
}

/// The control with `code`, when the PTP 3 reference defines it.
#[must_use]
pub fn control(code: ControlCode) -> Option<&'static ControlSpec> {
    CONTROLS
        .binary_search_by_key(&code.0, |spec| spec.code)
        .ok()
        .map(|index| &CONTROLS[index])
}

/// Documented label for a numeric property value, when the reference lists one.
#[must_use]
pub fn value_label(property: PropertyCode, value: i128) -> Option<&'static str> {
    VALUE_LABELS
        .binary_search_by_key(&(property.0, value), |row| (row.0, row.1))
        .ok()
        .map(|index| VALUE_LABELS[index].2)
}

/// Documented `(value, label)` rows for one property, in ascending value order.
pub fn property_labels(property: PropertyCode) -> impl Iterator<Item = (i128, &'static str)> {
    let start = VALUE_LABELS.partition_point(|row| row.0 < property.0);
    VALUE_LABELS[start..]
        .iter()
        .take_while(move |row| row.0 == property.0)
        .map(|row| (row.1, row.2))
}
